    "q": "由公安部与中央广播电视总台联合摄制的纪录片《缅北电诈覆灭纪实》于10月5日至7日在央视综合频道首播。影片全景展现了在党中央坚强领导下，我国公安机关会同有关部门开展打击缅北涉我犯罪专项工作、彻底铲除缅北“四大家族”等犯罪集团的艰辛历程。一度________的跨境电诈势力被连根拔起，边境地区社会秩序明显好转，人民群众的安全感显著提升。填入画横线部分最恰当的一项是：",
